//! Designated host for the generated `Class3Opt` simulation CLI — HAND-WRITTEN.
//!
//! The CLI body is generated by the `language!` macro into
//! `target/generated/class3opt/simulate.rs` (`options { emit_simulator: true }`, the
//! default) and materialized here by the `class3opt_simulation_main!` wrapper. This file is
//! the cargo `[[bin]]` target; its stanza lives in `languages/Cargo.toml`.
//!
//! `Class3Opt` is TEST-hosted: its definition is not a library module, so this binary
//! `#[path]`-includes the definition file directly and passes `crate::class3opt` to the
//! wrapper. Compiling that `mod` is also what RUNS the `language!` macro for this crate,
//! which is what writes the body the wrapper includes — the wrapper is emitted by that
//! same expansion, so the write always precedes the include.

#[path = "../../tests/definitions/class3opt.rs"]
mod class3opt;

class3opt::class3opt_simulation_main!(crate::class3opt);
